from datetime import date, timedelta


class Library:
    def __init__(self, loan_days: int = 14, daily_fine: float = 0.5) -> None:
        self.loan_days = loan_days
        self.daily_fine = daily_fine
        self.books = set()  # all book ids
        self.borrowed = {}  # book_id -> (user, borrow_day)
        self.fines = {}  # user -> unpaid fines
        self.user_books = {}  # user -> book_id (at most one due to rules)

    def add_book(self, book_id: str) -> None:
        self.books.add(book_id)

    def borrow(self, user: str, book_id: str, day: date) -> None:
        if book_id not in self.books:
            raise ValueError(f"Unknown book: {book_id}")
        if book_id in self.borrowed:
            raise ValueError(f"Book {book_id} is already borrowed")
        # Rule 1: user may hold at most one book at a time (even if fines unpaid)
        if user in self.user_books:
            raise ValueError(f"User {user} already holds a book")
        self.borrowed[book_id] = (user, day)
        self.user_books[user] = book_id

    def _count_delay_days(self, start: date, end: date) -> int:
        """Count weekdays in [start, end) inclusive of start, exclusive of end."""
        days = 0
        current = start
        while current < end:
            if current.weekday() < 5:  # Mon-Fri
                days += 1
            current += timedelta(days=1)
        return days

    def return_book(self, user: str, book_id: str, day: date) -> float:
        if book_id not in self.borrowed:
            raise ValueError(f"Book {book_id} is not borrowed")
        borrower, borrow_day = self.borrowed[book_id]
        if borrower != user:
            raise ValueError(f"Book {book_id} was not borrowed by {user}")

        due_day = borrow_day + timedelta(days=self.loan_days)

        fine = 0.0
        if day > due_day:
            # Days of delay: weekdays strictly after due_day up to and including day
            delay_days = self._count_delay_days(due_day + timedelta(days=1), day + timedelta(days=1))
            fine = round(delay_days * self.daily_fine, 2)

        del self.borrowed[book_id]
        if self.user_books.get(user) == book_id:
            del self.user_books[user]

        if fine > 0:
            self.fines[user] = self.fines.get(user, 0.0) + fine

        return fine

    def unpaid_fines(self, user: str) -> float:
        return self.fines.get(user, 0.0)

    def pay(self, user: str) -> None:
        if user in self.fines:
            del self.fines[user]
